// Reading passages, level 3 (C1-C2), ids 176-225. Loaded after reading.js and appended to READING.
// answer = index (0-3) of the correct option.
READING.push(
  {id: 176, level: 3, title: "The Ethics of Automation",
   text: "Proponents of automation argue that machines relieve humans of monotonous labor and may ultimately raise living standards. Critics counter that the gains are unevenly distributed, often accruing to firms that own the technology while displacing workers who lack the means to retrain. The debate is therefore less about efficiency than about who bears the transitional costs. Several economists have proposed mechanisms such as wage insurance or shared productivity dividends, though their feasibility remains contested.",
   questions: [{q: "What do proponents of automation believe it will do?", options: ["Increase unemployment", "Relieve humans of monotonous labor", "Eliminate all machines", "Reduce productivity"], answer: 1}, {q: "According to critics, who benefits most from automation?", options: ["Displaced workers", "Firms that own the technology", "Governments only", "Consumers in every case"], answer: 1}, {q: "What is the debate really about, according to the passage?", options: ["Whether machines work faster", "Who bears the transitional costs", "Whether robots can think", "The price of electricity"], answer: 1}]},
  {id: 177, level: 3, title: "Provenance of a Manuscript",
   text: "The manuscript, discovered in a private collection, purported to be a lost treatise on navigation. Scholars initially welcomed it, but closer examination revealed inconsistencies in the ink composition and the watermarks. Radiocarbon analysis placed the parchment several centuries later than the text claimed. Some researchers still maintain that the content may be authentic, arguing that a later copyist could have transcribed an earlier work, yet the prevailing view is that the document is a skilled forgery.",
   questions: [{q: "What was the manuscript claimed to be?", options: ["A medical textbook", "A lost treatise on navigation", "A collection of poems", "A royal decree"], answer: 1}, {q: "What did the analysis reveal about the parchment?", options: ["It was younger than the text claimed", "It was several centuries later than the text claimed", "It was blank", "It was made of paper"], answer: 1}, {q: "What is the prevailing view of the document?", options: ["It is authentic", "It is a skilled forgery", "It was lost again", "It is incomplete"], answer: 1}]},
  {id: 178, level: 3, title: "Urban Heat Islands",
   text: "Dense cities retain heat far more effectively than surrounding rural areas, a phenomenon known as the urban heat island effect. Asphalt, concrete, and tall buildings absorb solar radiation during the day and release it slowly after dusk. The consequences extend beyond discomfort: elevated nighttime temperatures increase energy demand and exacerbate heat-related illness among vulnerable populations. Planners increasingly favor reflective roofing, tree canopies, and permeable surfaces as relatively inexpensive mitigation strategies.",
   questions: [{q: "Why do cities retain more heat than rural areas?", options: ["They have more trees", "Materials absorb solar radiation and release it slowly", "They are colder at night", "They have more rivers"], answer: 1}, {q: "Which consequence is mentioned besides discomfort?", options: ["Lower energy demand", "Increased energy demand", "Less rainfall", "Cleaner air"], answer: 1}, {q: "Which mitigation strategy is NOT mentioned?", options: ["Reflective roofing", "Tree canopies", "Permeable surfaces", "Building more asphalt roads"], answer: 3}]},
  {id: 179, level: 3, title: "The Limits of Memory",
   text: "Eyewitness testimony is often regarded as compelling evidence, yet psychologists have repeatedly demonstrated that memory is reconstructive rather than reproductive. Each recall subtly alters the stored representation, and leading questions can implant details that never occurred. Confidence, moreover, is a poor indicator of accuracy: witnesses who are certain of their identifications are not always correct. Legal systems have responded by introducing procedural safeguards, although their effectiveness varies considerably.",
   questions: [{q: "How does the passage describe human memory?", options: ["As a perfect recording", "As reconstructive rather than reproductive", "As unchanging over time", "As unrelated to speech"], answer: 1}, {q: "What does the passage say about witness confidence?", options: ["It is a reliable sign of accuracy", "It is a poor indicator of accuracy", "It always decreases over time", "It is not measured"], answer: 1}, {q: "How have legal systems responded?", options: ["By abolishing eyewitness testimony", "By introducing procedural safeguards", "By ignoring the research", "By requiring longer trials"], answer: 1}]},
  {id: 180, level: 3, title: "Cartography and Power",
   text: "Maps are often perceived as neutral representations of geography, yet their construction involves selection, emphasis, and omission. Mercator's projection, for instance, distorts the relative size of landmasses near the poles, which historically inflated the apparent importance of certain regions. Scholars of critical cartography argue that maps reflect the priorities of those who commission them. Recognizing this does not render maps useless, but it encourages readers to ask what has been left out.",
   questions: [{q: "How are maps often perceived?", options: ["As biased documents", "As neutral representations of geography", "As works of art", "As historical fiction"], answer: 1}, {q: "What distortion does the Mercator projection cause?", options: ["It shrinks the oceans", "It distorts the relative size of landmasses near the poles", "It moves cities", "It removes rivers"], answer: 1}, {q: "What does the passage encourage readers to ask?", options: ["Who drew the map", "What has been left out", "How old the paper is", "Which colors were used"], answer: 1}]},
  {id: 181, level: 3, title: "Trust in Institutions",
   text: "Public trust in institutions tends to erode gradually rather than collapse in a single event. Surveys in several democracies reveal a pattern in which citizens initially express skepticism toward specific policies before extending doubt to the bodies that enacted them. Scholars disagree about the causes. Some emphasize economic insecurity, while others point to the fragmentation of media environments, which allows competing narratives to flourish. Restoring trust, they note, requires consistent performance over long periods rather than dramatic gestures.",
   questions: [{q: "How does public trust usually decline?", options: ["Suddenly, in one event", "Gradually", "It never declines", "Only after elections"], answer: 1}, {q: "What do some scholars blame for the decline?", options: ["Economic insecurity", "Too much sunlight", "Foreign tourism", "Lack of schools"], answer: 0}, {q: "What, according to the passage, is needed to restore trust?", options: ["Dramatic gestures", "Consistent performance over long periods", "New buildings", "Fewer laws"], answer: 1}]},
  {id: 182, level: 3, title: "The Sociolinguistics of Slang",
   text: "Slang is frequently dismissed as careless speech, yet it performs important social functions. It signals group membership, allowing speakers to mark affiliation with a particular community. It also evolves rapidly, which makes it a useful indicator of shifting values. Many terms that begin in marginal subcultures eventually enter mainstream usage, often stripped of their original connotations. Linguists therefore treat slang not as a corruption of standard language but as a dynamic register in its own right.",
   questions: [{q: "How is slang often dismissed?", options: ["As careful speech", "As careless speech", "As a foreign language", "As poetry"], answer: 1}, {q: "What social function does slang perform?", options: ["It hides meaning from everyone", "It signals group membership", "It replaces grammar", "It is used only in writing"], answer: 1}, {q: "How do linguists view slang?", options: ["As a corruption of standard language", "As a dynamic register in its own right", "As a dying form of speech", "As a mistake"], answer: 1}]},
  {id: 183, level: 3, title: "Fermentation and Flavor",
   text: "Fermentation transforms ordinary ingredients into complex foods through the metabolic activity of microorganisms. Lactic acid bacteria convert sugars into acids that preserve vegetables while producing distinctive tangy flavors. Yeasts, by contrast, generate carbon dioxide and alcohol, which give bread its texture and beer its character. Although industrial production has standardized many processes, artisans continue to rely on ambient microbial communities, accepting a degree of unpredictability in exchange for subtle, site-specific flavors.",
   questions: [{q: "What do lactic acid bacteria produce?", options: ["Alcohol", "Acids that preserve vegetables", "Carbon dioxide only", "Sugar"], answer: 1}, {q: "What do yeasts generate?", options: ["Acids only", "Carbon dioxide and alcohol", "Salt", "Fat"], answer: 1}, {q: "What do artisans accept in exchange for site-specific flavors?", options: ["Higher prices", "A degree of unpredictability", "Faster production", "Less flavor"], answer: 1}]},
  {id: 184, level: 3, title: "Deep Sea Exploration",
   text: "The deep ocean, defined as depths below two hundred meters, remains one of the least explored environments on Earth. Pressure at the greatest depths exceeds one thousand atmospheres, and sunlight never penetrates. Nevertheless, researchers have discovered ecosystems sustained by chemosynthesis, in which bacteria derive energy from chemicals released by hydrothermal vents. These findings have prompted speculation about the possibility of life in similar environments beyond our planet, particularly on icy moons where liquid water may exist beneath the surface.",
   questions: [{q: "How is the deep ocean defined in the passage?", options: ["Below two meters", "Below two hundred meters", "Below two thousand meters", "Below the surface only"], answer: 1}, {q: "How do some deep-sea bacteria obtain energy?", options: ["From sunlight", "From chemicals released by hydrothermal vents", "From eating fish", "From the air"], answer: 1}, {q: "Why has the discovery prompted speculation?", options: ["It proves the ocean is empty", "It suggests life may exist in similar environments elsewhere", "It shows the vents are dry", "It explains the moon's orbit"], answer: 1}]},
  {id: 185, level: 3, title: "The Economics of Attention",
   text: "In an information-rich environment, attention becomes the scarce resource. Platforms compete for user engagement, often by optimizing algorithms that prioritize content likely to provoke strong reactions. Critics argue that this incentive structure can distort public discourse, rewarding sensational material over nuanced analysis. Defenders reply that users retain agency and that the same systems can surface valuable information. The question, in essence, is whether the design of attention markets can be aligned with broader social goals.",
   questions: [{q: "What does the passage describe as scarce in an information-rich environment?", options: ["Money", "Attention", "Water", "Land"], answer: 1}, {q: "What do critics say algorithms reward?", options: ["Careful analysis", "Sensational material", "Silence", "Old news"], answer: 1}, {q: "What is the central question the passage raises?", options: ["Whether algorithms can be deleted", "Whether attention markets can be aligned with social goals", "Whether users can stop reading", "Whether advertising should be banned"], answer: 1}]},
  {id: 186, level: 3, title: "Restoring a Wetland",
   text: "The restoration project aimed to reverse decades of drainage that had transformed a fertile wetland into farmland. Engineers removed concrete channels and allowed seasonal flooding to resume. Early results were encouraging: native reeds returned, and waterbird populations increased within two years. However, the ecologists cautioned that the system remained fragile, since invasive species could quickly dominate disturbed soil. They recommended long-term monitoring, arguing that ecological recovery is measured in decades rather than seasons.",
   questions: [{q: "What had the wetland been turned into?", options: ["A city", "Farmland", "A desert", "A lake"], answer: 1}, {q: "What returned within two years?", options: ["Invasive species only", "Native reeds and more waterbirds", "Concrete channels", "Oil wells"], answer: 1}, {q: "Why did the ecologists recommend long-term monitoring?", options: ["Because the project was cheap", "Because ecological recovery takes decades", "Because the land was sold", "Because the reeds were removed"], answer: 1}]},
  {id: 187, level: 3, title: "Pricing Uncertainty",
   text: "Insurance markets depend on accurate estimates of risk, yet many hazards are difficult to quantify. Climate-related events, for example, have altered historical patterns that actuaries once relied upon. Insurers respond by raising premiums, restricting coverage, or withdrawing from certain regions altogether. Policymakers face a dilemma: unaffordable insurance may leave households exposed, while public backstops can encourage development in vulnerable areas. Resolving this tension requires coordination between financial institutions and governments.",
   questions: [{q: "What do insurance markets depend on?", options: ["Lucky guesses", "Accurate estimates of risk", "Government orders only", "Advertising"], answer: 1}, {q: "Why are historical patterns less useful now?", options: ["Climate-related events have altered them", "Paper records were lost", "Actuaries retired", "Insurance was banned"], answer: 0}, {q: "What is the policymakers' dilemma?", options: ["Whether to close banks", "Unaffordable insurance versus public backstops encouraging risky development", "Whether to build roads", "Whether to tax cars"], answer: 1}]},
  {id: 188, level: 3, title: "The Philosophy of Forgetting",
   text: "Philosophers have long debated whether forgetting is a deficiency or a necessary condition of a healthy mind. Nietzsche, for instance, suggested that the capacity to forget allows individuals to act decisively in the present. Modern neuroscience complicates this picture by showing that forgetting is an active process, mediated by synaptic changes that prune weak connections. Forgetting may thus be less a failure of memory than a mechanism through which the brain prioritizes information relevant to future decisions.",
   questions: [{q: "How is forgetting debated by philosophers?", options: ["As always harmful", "As a deficiency or a necessary condition", "As a myth", "As a form of sleep"], answer: 1}, {q: "What does modern neuroscience show about forgetting?", options: ["It is passive", "It is an active process", "It never happens", "It only affects children"], answer: 1}, {q: "According to the passage, what is forgetting thought to be?", options: ["A failure of memory", "A mechanism that prioritizes useful information", "A cause of illness", "A way to store more data"], answer: 1}]},
  {id: 189, level: 3, title: "Language Revitalization",
   text: "Many languages are spoken by only a handful of elderly speakers, and their disappearance represents a loss of unique knowledge about plants, kinship, and history. Revitalization efforts have had mixed results. Immersion schools, in which children are taught entirely in the threatened language, have shown the greatest promise. Yet such programs require substantial resources and trained teachers who may themselves be scarce. Community ownership of the process appears to be a decisive factor in whether revival efforts endure beyond the initial enthusiasm.",
   questions: [{q: "What is lost when a language disappears?", options: ["Only grammar", "Unique knowledge about plants, kinship, and history", "Only vocabulary for numbers", "Nothing important"], answer: 1}, {q: "Which approach has shown the greatest promise?", options: ["Textbooks alone", "Immersion schools", "Online games", "Radio broadcasts"], answer: 1}, {q: "What appears to decide whether revival endures?", options: ["Government announcements", "Community ownership of the process", "Foreign funding", "Tourism"], answer: 1}]},
  {id: 190, level: 3, title: "Autonomous Vehicles and Liability",
   text: "When an autonomous vehicle causes a collision, determining responsibility becomes legally complex. Traditional frameworks assign liability to drivers, yet the driver may have been a passenger without any control. Manufacturers, software developers, and infrastructure operators each play a role, and their contributions are often intertwined. Some jurisdictions have proposed strict liability for manufacturers, while others favor insurance pools that compensate victims regardless of fault. The outcome will shape both innovation and public confidence.",
   questions: [{q: "Why is liability complex for autonomous vehicles?", options: ["Vehicles are too expensive", "Traditional frameworks assign blame to drivers who may have had no control", "The roads are unclear", "Insurance is illegal"], answer: 1}, {q: "What has some jurisdiction proposed?", options: ["Banning vehicles", "Strict liability for manufacturers", "No responsibility for anyone", "Taxing passengers"], answer: 1}, {q: "What will the outcome shape?", options: ["Only the price of fuel", "Innovation and public confidence", "Only road signs", "Only weather patterns"], answer: 1}]},
  {id: 191, level: 3, title: "The Architecture of Silence",
   text: "Acousticians have long known that the design of concert halls profoundly affects how music is perceived. Reverberation time, the interval over which sound decays, must be carefully calibrated for each repertoire. A cathedral's long decay suits choral works, whereas chamber music benefits from a drier, more intimate acoustic. Modern architects increasingly use computer simulations to predict these effects before construction begins, though experienced listeners often judge a hall more by its subtle warmth than by any measurement.",
   questions: [{q: "What affects how music is perceived in concert halls?", options: ["The color of the seats", "The design of the hall", "The price of tickets", "The weather"], answer: 1}, {q: "What suits choral works?", options: ["A dry acoustic", "A cathedral's long decay", "No reverberation", "Open air"], answer: 1}, {q: "How do experienced listeners often judge a hall?", options: ["By its size", "By its subtle warmth", "By the number of seats", "By its parking"], answer: 1}]},
  {id: 192, level: 3, title: "Microfinance Reconsidered",
   text: "Microfinance was once celebrated as a powerful tool for poverty alleviation, offering small loans to entrepreneurs excluded from formal banking. Rigorous evaluations, however, have produced more nuanced findings. Average effects on household income appear modest, and some borrowers accumulate debt they struggle to repay. Advocates respond that microfinance provides financial stability and flexibility rather than dramatic transformation. The current consensus favors combining credit with savings products, training, and social protection.",
   questions: [{q: "How was microfinance once described?", options: ["As a failure", "As a powerful tool for poverty alleviation", "As a tax", "As a bank scandal"], answer: 1}, {q: "What do rigorous evaluations show about income effects?", options: ["Dramatic growth", "Modest average effects", "Large losses", "No data exists"], answer: 1}, {q: "What does the current consensus favor?", options: ["Credit only", "Combining credit with savings, training, and social protection", "Abolishing loans", "Cash donations only"], answer: 1}]},
  {id: 193, level: 3, title: "Ocean Acidification",
   text: "As the oceans absorb roughly a quarter of the carbon dioxide released by human activity, their chemistry shifts toward greater acidity. This process reduces the availability of carbonate ions, which many marine organisms require to build shells and skeletons. Coral reefs, pteropods, and certain shellfish are especially vulnerable. Although the chemical mechanism is well understood, the biological responses are highly variable, and some species appear capable of adapting over successive generations.",
   questions: [{q: "What do the oceans absorb?", options: ["Only sunlight", "Roughly a quarter of human carbon dioxide", "Plastic only", "Heat only"], answer: 1}, {q: "What do many marine organisms need that acidification reduces?", options: ["Oxygen", "Carbonate ions", "Sunlight", "Salt"], answer: 1}, {q: "What does the passage say about biological responses?", options: ["They are identical in all species", "They are highly variable", "They are absent", "They are fully predictable"], answer: 1}]},
  {id: 194, level: 3, title: "Translating Poetry",
   text: "Translating poetry involves a set of compromises that prose rarely demands. The translator must decide whether to preserve rhyme, meter, or the literal sense of each line, knowing that gaining one often means sacrificing another. Some theorists argue that the goal should be recreating the poem's effect rather than its surface. Others insist that fidelity to form is itself a form of respect. Most translators, in practice, navigate between these positions, accepting that every version is a new poem in its own right.",
   questions: [{q: "What must a poetry translator decide?", options: ["The price of the book", "Whether to preserve rhyme, meter, or literal sense", "The font size", "The cover design"], answer: 1}, {q: "What do some theorists say the goal should be?", options: ["Copying the surface exactly", "Recreating the poem's effect", "Ignoring the original", "Shortening the poem"], answer: 1}, {q: "How does the passage describe a translated version?", options: ["As a copy", "As a new poem in its own right", "As a mistake", "As an outline"], answer: 1}]},
  {id: 195, level: 3, title: "The Ethics of Gene Editing",
   text: "Gene editing technologies have made it possible to modify the DNA of living organisms with unprecedented precision. Applications range from treating inherited diseases to improving crop resistance to drought. Yet the same tools raise questions about consent, especially when changes affect future generations who cannot agree to them. Bioethicists generally distinguish between somatic modifications, which affect only the treated individual, and germline modifications, which are inherited. Many countries currently prohibit the latter, though debates about its eventual permissibility continue.",
   questions: [{q: "What can gene editing do?", options: ["Only predict weather", "Modify DNA with great precision", "Create new planets", "Erase memories"], answer: 1}, {q: "Why is consent a concern?", options: ["Because the tools are expensive", "Because future generations cannot agree to changes that affect them", "Because it is too fast", "Because the tools are public"], answer: 1}, {q: "What distinction do bioethicists make?", options: ["Between cheap and expensive methods", "Between somatic and germline modifications", "Between plants and animals", "Between day and night"], answer: 1}]},
  {id: 196, level: 3, title: "Reconstructing a Ruin",
   text: "Archaeologists excavating a Bronze Age settlement uncovered evidence that its inhabitants had rebuilt the same walls several times over three centuries. The layers suggest repeated flooding rather than warfare, a conclusion supported by sediment analysis. Restoration teams must now decide whether to preserve the stratigraphy visible in the trenches or to reconstruct the walls for public display. Each option involves trade-offs between scientific integrity and the visitor experience, and the decision has sparked lively debate among specialists.",
   questions: [{q: "What did the archaeologists find?", options: ["The walls were rebuilt several times", "The settlement was never built", "Gold coins", "A modern road"], answer: 0}, {q: "What do the layers suggest caused the damage?", options: ["Warfare", "Repeated flooding", "Earthquakes only", "Fire"], answer: 1}, {q: "What trade-off do the restoration teams face?", options: ["Cost versus color", "Scientific integrity versus visitor experience", "Speed versus size", "Light versus darkness"], answer: 1}]},
  {id: 197, level: 3, title: "Remote Sensing of Forests",
   text: "Satellite imagery now allows scientists to monitor forest cover across entire continents at regular intervals. Machine learning algorithms can distinguish between natural regrowth and clearing for agriculture with growing accuracy. However, cloud cover, seasonal variation, and differences in sensor resolution complicate comparisons over time. Experts caution that remote data should be validated with ground surveys, since satellites cannot easily detect selective logging or the health of individual trees.",
   questions: [{q: "What can satellite imagery do?", options: ["Predict earthquakes", "Monitor forest cover across continents", "Measure ocean salt", "Count birds"], answer: 1}, {q: "What complicates comparisons over time?", options: ["Only the price of satellites", "Cloud cover, seasonal variation, and sensor resolution", "Lack of trees", "Bad software"], answer: 1}, {q: "What do experts say should validate remote data?", options: ["Opinions", "Ground surveys", "Weather reports", "Stock prices"], answer: 1}]},
  {id: 198, level: 3, title: "Labor and Automation in Agriculture",
   text: "Mechanized harvesters have transformed agriculture, reducing the need for seasonal labor in many regions. Economists disagree about the long-term consequences. Some argue that displaced workers will move into higher-skilled occupations, following the historical pattern of previous technological shifts. Others contend that the scale of current automation is unprecedented and that the transition may be far more disruptive. Local policies, including investment in rural education, may determine which trajectory prevails.",
   questions: [{q: "What has mechanized harvesting reduced?", options: ["The need for machines", "The need for seasonal labor", "The price of seeds", "The size of farms"], answer: 1}, {q: "What do optimistic economists expect?", options: ["Workers will disappear", "Workers will move into higher-skilled jobs", "Farms will close", "Machines will stop"], answer: 1}, {q: "What may determine the outcome, according to the passage?", options: ["Weather only", "Local policies such as rural education investment", "The color of tractors", "Foreign imports only"], answer: 1}]},
  {id: 199, level: 3, title: "Bureaucracy and Discretion",
   text: "Formal rules attempt to make public administration predictable, yet frontline officials inevitably exercise discretion when applying them. Sociologists have documented how workers in welfare offices develop informal routines to manage high caseloads, sometimes interpreting regulations in ways that diverge from their letter. Such adaptations can be pragmatic, but they can also produce inconsistent treatment of citizens. Reformers therefore face a delicate balance between constraining discretion and preserving the judgment that complex cases require.",
   questions: [{q: "What do formal rules aim to do?", options: ["Eliminate all officials", "Make public administration predictable", "Increase paperwork only", "Replace citizens"], answer: 1}, {q: "What informal behavior did sociologists document?", options: ["Officials refusing to work", "Informal routines to manage high caseloads", "Bribery in all cases", "Unpaid holidays"], answer: 1}, {q: "What is the reformers' challenge?", options: ["Removing all rules", "Balancing constraint on discretion with judgment for complex cases", "Increasing fees", "Closing offices"], answer: 1}]},
  {id: 200, level: 3, title: "The Measurement of Time",
   text: "Standard time was once a local convention, varying from town to town according to the position of the sun. The expansion of railways made such diversity impractical, prompting the adoption of standardized time zones. Today, atomic clocks define the second with extraordinary precision, based on the frequency of radiation emitted by cesium atoms. Yet even these measurements must be periodically adjusted, since the rotation of the Earth is slightly irregular.",
   questions: [{q: "Why was local time once used?", options: ["It was official law", "Time varied according to the position of the sun", "Clocks did not exist", "Railways required it"], answer: 1}, {q: "What made standard time zones necessary?", options: ["Telephones", "The expansion of railways", "Electric lights", "Newspapers"], answer: 1}, {q: "Why must atomic time be adjusted?", options: ["Atoms change size", "The Earth's rotation is slightly irregular", "Clocks break often", "Cesium is unstable in air"], answer: 1}]},
  {id: 201, level: 3, title: "Scientific Consensus",
   text: "Scientific consensus is rarely the product of a single decisive experiment. It emerges gradually as independent teams replicate results, challenge assumptions, and refine methods. Critics sometimes portray consensus as an exercise in authority, yet the process depends on the willingness of researchers to abandon positions that the evidence no longer supports. Public confusion often arises when preliminary findings are reported as settled conclusions, obscuring the iterative nature of the enterprise.",
   questions: [{q: "How does scientific consensus usually emerge?", options: ["From one decisive experiment", "Gradually, through replication and refinement", "By vote in parliament", "By magazine articles"], answer: 1}, {q: "What do critics sometimes claim consensus is?", options: ["An accident", "An exercise in authority", "A joke", "A mathematical proof"], answer: 1}, {q: "What causes public confusion, according to the passage?", options: ["Silence from scientists", "Preliminary findings reported as settled conclusions", "Too many experiments", "Lack of funding"], answer: 1}]},
  {id: 202, level: 3, title: "Coastal Fisheries Management",
   text: "Quota systems were introduced to prevent overfishing by setting annual limits on catches. In theory, they protect stock levels while maintaining livelihoods. In practice, the allocation of quotas often becomes contentious, since historical catches may favor larger operators. Some fishing communities have pioneered co-management arrangements in which local fishers help monitor stocks and set rules. Such approaches appear to improve compliance, although they require sustained trust between regulators and the people they regulate.",
   questions: [{q: "What do quota systems set?", options: ["Prices for fish", "Annual limits on catches", "The number of boats", "The fishing seasons"], answer: 1}, {q: "Why does quota allocation become contentious?", options: ["Fish are rare", "Historical catches may favor larger operators", "Boats are expensive", "Ports are closed"], answer: 1}, {q: "What do co-management arrangements require?", options: ["Foreign experts only", "Sustained trust between regulators and fishers", "No rules at all", "Larger boats"], answer: 1}]},
  {id: 203, level: 3, title: "Written Versus Spoken Discourse",
   text: "Speech and writing differ in ways that extend far beyond their medium. Spoken discourse is often fragmentary and relies on shared context, intonation, and gesture to convey meaning. Written prose, by contrast, must be self-contained and tends toward complex syntax and carefully hedged claims. Linguists observe that these differences have become less rigid in digital communication, where informal written messages mimic the rhythm of conversation. The boundary between the two modes is therefore increasingly porous.",
   questions: [{q: "What does spoken discourse rely on?", options: ["Only grammar", "Shared context, intonation, and gesture", "Printed text", "Long sentences"], answer: 1}, {q: "What must written prose be?", options: ["Fragmentary", "Self-contained", "Silent", "Brief only"], answer: 1}, {q: "What has happened to the boundary in digital communication?", options: ["It has become fixed", "It has become more porous", "It has disappeared completely", "It has moved to speech"], answer: 1}]},
  {id: 204, level: 3, title: "Geothermal Potential",
   text: "Geothermal energy harnesses heat stored beneath the Earth's surface, offering a steady supply largely independent of weather. Traditional installations are concentrated in volcanically active regions, where hot water reaches the surface naturally. Enhanced geothermal systems aim to extend the technology to areas lacking such features by fracturing hot rock and circulating water through it. Early projects have encountered seismic concerns and high drilling costs, leaving the economic viability of the approach uncertain.",
   questions: [{q: "What makes geothermal energy attractive?", options: ["It depends on wind", "It offers a steady supply independent of weather", "It needs sunlight", "It is very cheap to build"], answer: 1}, {q: "Where are traditional installations concentrated?", options: ["In deserts", "In volcanically active regions", "In large cities", "In forests"], answer: 1}, {q: "What concerns have early enhanced projects faced?", options: ["Too much rain", "Seismic concerns and high drilling costs", "Lack of hot rock", "Shortage of water only"], answer: 1}]},
  {id: 205, level: 3, title: "The Ethics of Zoos",
   text: "Zoos have shifted their purpose over the past century from entertainment toward conservation and education. Proponents argue that breeding programs have saved several species from extinction and that visitors develop empathy for wildlife. Critics question whether confinement can be justified when animals' natural behaviors are severely constrained. Many institutions now invest in larger enclosures and enrichment activities, although the underlying ethical question about captivity remains open for debate.",
   questions: [{q: "What has the purpose of zoos shifted toward?", options: ["Military training", "Conservation and education", "Mining", "Farming"], answer: 1}, {q: "What do proponents say breeding programs have done?", options: ["Destroyed habitats", "Saved several species from extinction", "Increased poaching", "Ended tourism"], answer: 1}, {q: "What do many institutions now do?", options: ["Close all enclosures", "Invest in larger enclosures and enrichment", "Sell all animals", "Stop all education"], answer: 1}]},
  {id: 206, level: 3, title: "Neighborhood Gentrification",
   text: "Gentrification is often portrayed as a single process, yet its effects vary considerably across neighborhoods. Investment can revitalize derelict buildings and attract new businesses, improving services for existing residents. At the same time, rising rents may displace long-standing tenants who lack the means to remain. Researchers emphasize that outcomes depend heavily on local protections, such as tenant rights and the availability of affordable housing. Without such safeguards, revitalization can become a form of exclusion.",
   questions: [{q: "How is gentrification often portrayed?", options: ["As many unrelated processes", "As a single process", "As a holiday", "As a tax"], answer: 1}, {q: "What can rising rents cause?", options: ["Lower crime only", "Displacement of long-standing tenants", "Free housing", "More farming"], answer: 1}, {q: "What do outcomes depend on, according to researchers?", options: ["Weather", "Local protections such as tenant rights", "The color of buildings", "Foreign tourists"], answer: 1}]},
  {id: 207, level: 3, title: "Musical Notation and Memory",
   text: "Musical notation was developed partly to aid memory, allowing performers to recall long compositions without relying solely on oral transmission. Yet many musicians of earlier eras memorized vast repertoires, and some oral traditions persist without written scores. Cognitive scientists have found that musical structure, with its repetitions and patterns, supports recall in ways that prose cannot easily match. The relationship between writing and memory in music is thus more reciprocal than a simple story of progress would suggest.",
   questions: [{q: "Why was musical notation partly developed?", options: ["To make instruments", "To aid memory", "To sell records", "To replace performers"], answer: 1}, {q: "What do some oral traditions do?", options: ["Disappear quickly", "Persist without written scores", "Require computers", "Use only drums"], answer: 1}, {q: "How does the passage describe the relationship between writing and memory in music?", options: ["Simple progress", "More reciprocal than a simple story of progress", "Irrelevant", "Entirely negative"], answer: 1}]},
  {id: 208, level: 3, title: "The Problem of Induction",
   text: "Philosophers since antiquity have wrestled with the question of how general conclusions can be justified by particular observations. Past experience, however extensive, does not logically guarantee future regularities. Hume argued that our confidence in induction rests on habit rather than reason. Subsequent thinkers have proposed pragmatic defenses, suggesting that inductive methods succeed well enough in practice. The debate remains unresolved, yet scientific practice continues largely unhindered by it.",
   questions: [{q: "What is the core question of the passage?", options: ["How to cook", "How general conclusions can be justified by particular observations", "How to sail", "How to write poems"], answer: 1}, {q: "What did Hume argue?", options: ["Induction is perfectly logical", "Confidence in induction rests on habit rather than reason", "Observations are useless", "Induction is only for mathematics"], answer: 1}, {q: "What is said about scientific practice?", options: ["It has stopped", "It continues largely unhindered by the debate", "It depends entirely on the debate", "It is impossible"], answer: 1}]},
  {id: 209, level: 3, title: "Hydrogen as an Energy Carrier",
   text: "Hydrogen is often proposed as a clean energy carrier, capable of storing surplus electricity from renewable sources. When used in fuel cells, it produces only water as a byproduct. However, most hydrogen today is manufactured from natural gas, a process that releases substantial carbon dioxide. Producing hydrogen through electrolysis is cleaner but requires considerable electricity. The environmental benefit therefore depends heavily on how the hydrogen itself is made.",
   questions: [{q: "What can hydrogen store?", options: ["Water", "Surplus electricity from renewable sources", "Heat only", "Oxygen"], answer: 1}, {q: "What does a hydrogen fuel cell produce as a byproduct?", options: ["Carbon dioxide", "Only water", "Smoke", "Sulfur"], answer: 1}, {q: "On what does the environmental benefit depend?", options: ["The color of the tank", "How the hydrogen is made", "The price of gas", "The size of the car"], answer: 1}]},
  {id: 210, level: 3, title: "Oral Histories of Migration",
   text: "Oral histories collected from migrants offer perspectives often absent from official records. Interviewers encounter narratives that are shaped by memory, identity, and the desire to present a coherent life story. Historians debate how to treat these accounts: some regard them as valuable evidence of subjective experience, while others caution that memory can compress or reorder events. Many contemporary projects therefore combine interviews with documents, photographs, and archival sources to build a more complete picture.",
   questions: [{q: "What do oral histories from migrants offer?", options: ["Perspectives often absent from official records", "Exact statistics", "Official laws", "Stock prices"], answer: 0}, {q: "What shapes these narratives?", options: ["Only grammar", "Memory, identity, and the desire for a coherent story", "Weather", "Official orders"], answer: 1}, {q: "How do many projects build a more complete picture?", options: ["By ignoring interviews", "By combining interviews with documents and archival sources", "By using only photographs", "By avoiding memory"], answer: 1}]},
  {id: 211, level: 3, title: "Biodiversity and Pharmaceuticals",
   text: "Many modern medicines originated from compounds discovered in plants, fungi, and microorganisms. The search for new therapeutics has therefore long depended on biodiversity, particularly in tropical ecosystems. Yet habitat loss threatens species that may never have been catalogued. Pharmaceutical companies have also become more cautious about bioprospecting, partly due to disputes over benefit-sharing with the communities that hold traditional knowledge. Fair agreements are increasingly seen as essential to sustainable research.",
   questions: [{q: "Where did many modern medicines originate?", options: ["Only in laboratories", "In compounds from plants, fungi, and microorganisms", "In factories only", "In animals only"], answer: 1}, {q: "What threatens undiscovered species?", options: ["Tourism", "Habitat loss", "Sunlight", "Music"], answer: 1}, {q: "What has made companies more cautious?", options: ["Lower prices", "Disputes over benefit-sharing with communities", "Shorter flights", "Better weather"], answer: 1}]},
  {id: 212, level: 3, title: "The Arts Funding Debate",
   text: "Public funding for the arts is justified by different rationales. Some argue that cultural institutions produce intrinsic value that markets undervalue. Others emphasize instrumental benefits, such as tourism revenue or improved educational outcomes. Critics respond that instrumental arguments distort artistic practice by encouraging work that satisfies measurable targets. Policy makers often attempt to balance these perspectives, yet the criteria for success remain contested.",
   questions: [{q: "What do some argue cultural institutions produce?", options: ["Only profit", "Intrinsic value that markets undervalue", "Pollution", "Traffic"], answer: 1}, {q: "What are instrumental benefits?", options: ["Benefits to the arts only", "Benefits such as tourism revenue or educational outcomes", "Costs of art", "Art materials"], answer: 1}, {q: "What do critics say instrumental arguments encourage?", options: ["Work that satisfies measurable targets", "Silence", "Abstract painting only", "Closing theatres"], answer: 0}]},
  {id: 213, level: 3, title: "Tidal Power Prospects",
   text: "Tidal power exploits the predictable rise and fall of seawater to generate electricity. Its regularity is a clear advantage over intermittent sources, since tides can be forecast decades in advance. Nevertheless, tidal barrages are expensive to build and can alter sediment flows and marine habitats. Newer designs, such as underwater turbines placed in fast currents, aim to reduce these impacts. Their commercial future depends on whether reliability can compensate for higher initial costs.",
   questions: [{q: "What does tidal power use?", options: ["Wind", "The rise and fall of seawater", "Sunlight", "Volcanic heat"], answer: 1}, {q: "What is its main advantage?", options: ["It is cheap", "Tides are predictable and forecastable", "It needs no maintenance", "It works without water"], answer: 1}, {q: "What do newer designs aim to do?", options: ["Increase sediment flows", "Reduce impacts on sediment and habitats", "Eliminate turbines", "Move power to land"], answer: 1}]},
  {id: 214, level: 3, title: "Counterfactual Histories",
   text: "Counterfactual history asks what might have happened had a pivotal event unfolded differently. Critics dismiss the genre as speculation untethered from evidence. Defenders argue that disciplined counterfactuals clarify causal claims by isolating which factors were necessary and which were merely incidental. The most rigorous versions specify plausible alternative conditions and examine their consequences systematically. Even when the answers remain uncertain, the exercise can expose hidden assumptions in conventional narratives.",
   questions: [{q: "What does counterfactual history ask?", options: ["What will happen tomorrow", "What might have happened had an event unfolded differently", "What is the weather", "What is the price of land"], answer: 1}, {q: "What do defenders say disciplined counterfactuals clarify?", options: ["Recipes", "Causal claims", "Music theory", "Geography"], answer: 1}, {q: "What can the exercise expose?", options: ["Hidden assumptions in conventional narratives", "Bad weather", "Lost keys", "Fashion trends"], answer: 0}]},
  {id: 215, level: 3, title: "Protein Folding",
   text: "Proteins perform nearly every function in living cells, and their activity depends on the three-dimensional shape they adopt after synthesis. Misfolded proteins are implicated in several neurodegenerative diseases. For decades, predicting a protein's structure from its amino acid sequence remained one of biology's great challenges. Recent computational advances have dramatically improved these predictions, although experimental confirmation remains essential, particularly for proteins that interact with other molecules.",
   questions: [{q: "What determines a protein's activity?", options: ["Its color", "The three-dimensional shape it adopts", "Its size only", "Its location in the sky"], answer: 1}, {q: "What are misfolded proteins linked to?", options: ["Broken bones", "Several neurodegenerative diseases", "Colds", "Skin rashes"], answer: 1}, {q: "What remains essential despite computational advances?", options: ["Guessing", "Experimental confirmation", "Ignoring data", "Stopping research"], answer: 1}]},
  {id: 216, level: 3, title: "Plural Governance",
   text: "Water resources in many regions are governed by overlapping institutions, each with partial authority. National ministries, local councils, and customary communities may all claim a role in allocating supplies. Scholars of institutional design argue that such polycentric arrangements can be resilient, because failure in one node does not paralyze the whole system. However, coordination costs can be substantial, and conflicting mandates sometimes leave marginal users without effective representation.",
   questions: [{q: "How are water resources often governed?", options: ["By one institution only", "By overlapping institutions with partial authority", "By private corporations only", "By no one"], answer: 1}, {q: "Why can polycentric arrangements be resilient?", options: ["They are cheaper", "Failure in one node does not paralyze the whole system", "They are faster", "They have no rules"], answer: 1}, {q: "What is a drawback mentioned?", options: ["Too much rain", "Substantial coordination costs", "Lack of water", "Excess sunlight"], answer: 1}]},
  {id: 217, level: 3, title: "The Chemistry of Color",
   text: "Pigments derive their color from the way their molecules absorb certain wavelengths of light while reflecting others. Historically, painters relied on minerals and plant extracts, many of which were toxic or unstable. The synthesis of new dyes in the nineteenth century transformed both art and industry, offering brilliant hues that were previously unavailable. Conservators now analyze these materials to understand how paintings age, since some synthetic pigments fade in ways that the original artists could not have anticipated.",
   questions: [{q: "How do pigments derive their color?", options: ["From heat", "By absorbing some wavelengths and reflecting others", "From sound", "From water alone"], answer: 1}, {q: "What did painters historically rely on?", options: ["Plastic", "Minerals and plant extracts", "Electricity", "Glass"], answer: 1}, {q: "Why do conservators analyze materials?", options: ["To sell paintings", "To understand how paintings age", "To make dyes illegal", "To remove colors"], answer: 1}]},
  {id: 218, level: 3, title: "Urban Water Infrastructure",
   text: "Aging water infrastructure in many cities loses a significant share of treated water through leaks before it reaches consumers. Replacing pipes is expensive and disruptive, so utilities often prioritize sections with the highest failure rates. Predictive models that combine pressure data with pipe age and soil conditions have improved the targeting of repairs. Yet financing remains the central obstacle, since the benefits of maintenance are gradual while the costs are immediate and visible.",
   questions: [{q: "What happens to treated water in aging systems?", options: ["It is doubled", "A significant share is lost through leaks", "It becomes sweet", "It freezes"], answer: 1}, {q: "How do utilities decide where to repair?", options: ["Randomly", "By prioritizing sections with the highest failure rates", "By color", "By district population only"], answer: 1}, {q: "Why is financing difficult?", options: ["Water is free", "The benefits are gradual while the costs are immediate", "Pipes are cheap", "No one needs water"], answer: 1}]},
  {id: 219, level: 3, title: "The Sociology of Queues",
   text: "Queues appear mundane, yet they reveal much about social norms. Sociologists have observed that people in many societies queue in orderly lines, while in others crowding around a counter is accepted. Perceptions of fairness are central: a visible line signals that everyone is treated equally, whereas its absence can suggest favoritism. Organizations that understand this often design waiting areas carefully, since even a modest sense of order can reduce frustration and complaints.",
   questions: [{q: "What do queues reveal, according to the passage?", options: ["Only traffic patterns", "Much about social norms", "Nothing important", "Only weather"], answer: 1}, {q: "What does a visible line signal?", options: ["Favoritism", "That everyone is treated equally", "A broken system", "A closed office"], answer: 1}, {q: "What can a modest sense of order reduce?", options: ["Trust", "Frustration and complaints", "Employment", "Light"], answer: 1}]},
  {id: 220, level: 3, title: "Interpreting Ancient Texts",
   text: "Scholars who edit ancient texts must reconstruct damaged passages from fragments that survive in different manuscripts. Each copyist introduced errors, sometimes deliberately modernizing the language or clarifying obscure references. Textual critics therefore compare witnesses to identify the most probable original reading. Their conclusions are always provisional, since new discoveries may overturn established judgments. The discipline thrives on this tension between certainty and revision.",
   questions: [{q: "What must editors do with damaged passages?", options: ["Ignore them", "Reconstruct them from surviving fragments", "Burn them", "Translate them into music"], answer: 1}, {q: "What did copyists sometimes do?", options: ["Stop writing", "Modernize the language or clarify references", "Use only pictures", "Translate everything into Greek"], answer: 1}, {q: "Why are conclusions always provisional?", options: ["Scholars are careless", "New discoveries may overturn established judgments", "Texts are fake", "Ink fades"], answer: 1}]},
  {id: 221, level: 3, title: "Digital Currency Trade-Offs",
   text: "Digital currencies promise faster settlement and reduced reliance on intermediaries. Their proponents highlight the potential for financial inclusion in regions where banking access is limited. Critics, however, point to price volatility, vulnerability to cyberattacks, and the difficulty of consumer protection when transactions are irreversible. Central banks studying digital money often weigh these risks against the benefits of improving payment efficiency, and their designs typically emphasize stability over speculation.",
   questions: [{q: "What do digital currencies promise?", options: ["Slower payments", "Faster settlement and fewer intermediaries", "Higher taxes", "Paper money"], answer: 1}, {q: "What do critics point to?", options: ["Stable prices only", "Price volatility and cyberattack risks", "Too many banks", "Lack of phones"], answer: 1}, {q: "What do central banks typically emphasize in their designs?", options: ["Speculation", "Stability over speculation", "Anonymity only", "Gold reserves"], answer: 1}]},
  {id: 222, level: 3, title: "Playing Chess Against Machines",
   text: "When a computer first defeated a reigning world champion, many observers predicted the end of human chess. Instead, the game flourished. Players now use engines to test ideas and uncover weaknesses in their preparation. Some commentators worry that reliance on machines has homogenized opening choices, although others note that human creativity still produces surprising plans. The episode illustrates how technologies often reshape a practice rather than simply replacing it.",
   questions: [{q: "What did many observers predict after the computer's victory?", options: ["Chess would grow", "The end of human chess", "Chess would become a sport", "Computers would stop playing"], answer: 1}, {q: "What did the game actually do?", options: ["Disappear", "Flourish", "Become illegal", "Stop being studied"], answer: 1}, {q: "What do some commentators worry about?", options: ["Lack of food", "That machines have homogenized opening choices", "Too many players", "Dull boards"], answer: 1}]},
  {id: 223, level: 3, title: "The Limits of Forecasting",
   text: "Economic forecasts often convey a precision that the underlying models cannot justify. Small errors in initial assumptions compound over time, producing projections that diverge sharply from outcomes. Forecasters respond by reporting ranges rather than single figures, yet audiences frequently remember only the central estimate. Some institutions have begun publishing their track records, allowing observers to judge reliability. Humility about prediction, the critics say, should be a professional virtue rather than an afterthought.",
   questions: [{q: "What do economic forecasts often convey?", options: ["Vagueness", "A precision that models cannot justify", "No numbers", "Perfect accuracy"], answer: 1}, {q: "What do forecasters report to reflect uncertainty?", options: ["Only colors", "Ranges rather than single figures", "Nothing", "Riddles"], answer: 1}, {q: "What do critics say should be a professional virtue?", options: ["Speed", "Humility about prediction", "Secrecy", "Confidence without evidence"], answer: 1}]},
  {id: 224, level: 3, title: "Coral Reef Resilience",
   text: "Coral reefs support a remarkable concentration of marine life, yet they have suffered widespread bleaching during recent warm periods. When water temperatures rise, corals expel the symbiotic algae that provide much of their energy. Some reefs recover within a few years, while others collapse entirely. Researchers have identified certain reef sites that appear more resilient, possibly because of cooler currents or genetically tolerant coral populations. Protecting these refuges is becoming a priority for conservation planners.",
   questions: [{q: "What do coral reefs support?", options: ["Very little life", "A remarkable concentration of marine life", "Only fish", "Only plants"], answer: 1}, {q: "Why do corals bleach?", options: ["They eat too much", "They expel symbiotic algae when water warms", "They grow too fast", "They are hit by fish"], answer: 1}, {q: "What do conservation planners now prioritize?", options: ["Building resorts", "Protecting resilient refuges", "Removing all coral", "Ignoring reefs"], answer: 1}]},
  {id: 225, level: 3, title: "Consensus Decision-Making",
   text: "Consensus decision-making, in which groups seek agreement rather than majority votes, is often praised for inclusiveness. Its proponents argue that it surfaces minority concerns and produces commitments that members feel ownership of. Critics note that the process can be slow and may allow a single determined participant to block progress. Facilitators have developed techniques such as proposals with stated objections and time limits to balance thoroughness against efficiency. The method works best in groups that share strong norms of mutual respect.",
   questions: [{q: "What does consensus decision-making seek?", options: ["A majority vote", "Agreement among members", "A random choice", "A leader's order"], answer: 1}, {q: "What do critics say about it?", options: ["It is too fast", "It can be slow and may let one participant block progress", "It excludes everyone", "It requires no talking"], answer: 1}, {q: "When does the method work best, according to the passage?", options: ["In groups with strong norms of mutual respect", "In large crowds", "In groups without rules", "In silent groups"], answer: 0}]}
);
